57. pub struct ExPageTableAddress(PageTableAddress);
58. 
59. #[verifier::external_type_specification]
60. #[verifier::external_body]
61. pub struct ExPageDirectoryAddress(PageDirectoryAddress);
62. 
63. #[verifier::reject_recursive_types(T)]
64. #[verifier::external_type_specification]
65. #[verifier::external_body]
66. pub struct ExPageTableAligned<T: Address>(PageTableAligned<T>);
67. 
68. // --- MMU paging types (generic over storage) ---
69. 
